insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1106, 'Best Streak', 'A trader writes down the profit (possibly negative) of every day. Find the largest total profit of a block of consecutive days. The block must contain at least one day.', 'The first line contains n (1 ≤ n ≤ 2·10^4). The second line contains n integers (|a_i| ≤ 10^9).', 'Print the maximum sum of a non-empty contiguous block.', 'Try Kadane''s algorithm: keep the best sum of a block that ends today.', '[{"input":"8\n-2 1 -3 4 -1 2 1 -5\n","output":"6"},{"input":"2\n-3 -1\n","output":"-1"}]'::jsonb, array['dp','greedy']::text[], 1500, 2000, 'hidden') on conflict (id) do nothing;
