insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1111, 'Robot Walk', 'A robot starts at (0, 0). Each letter moves it one step: `U` y+1, `D` y−1, `L` x−1, `R` x+1. Print its final position and the number of different cells it visited (including the start).', 'One line with the moves, length 1 to 2·10^4.', 'Print x, y and the number of visited cells, separated by spaces.', '', '[{"input":"URDL\n","output":"0 0 4"},{"input":"RRR\n","output":"3 0 4"}]'::jsonb, array['implementation','data structures']::text[], 1200, 2000, 'hidden') on conflict (id) do nothing;
