insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1112, 'Booking Calendar', 'A room has n bookings, each from day l to day r inclusive. Merge bookings that overlap or touch (e.g. [1, 3] and [4, 6] touch because day 4 follows day 3) and print the merged bookings in order.', 'The first line contains n (1 ≤ n ≤ 2·10^4). Each of the next n lines contains l and r (1 ≤ l ≤ r ≤ 10^9).', 'Print the number of merged bookings, then each one as `l r` on its own line, sorted by l.', '', '[{"input":"4\n1 3\n8 10\n2 5\n6 6\n","output":"2\n1 6\n8 10"}]'::jsonb, array['sortings','greedy']::text[], 1500, 2000, 'hidden') on conflict (id) do nothing;
